settings.customcss:
/* * system24 (Black Edition) for YouTube
 * Based on system24 by refact0r
 */

@import url('https://fonts.googleapis.com/css2?family=DM+Mono:ital,wght@0,300;0,400;0,500;1,300;1,400;1,500&display=swap');

:root {
    /* --- System24 Variables --- */
    --font-system24: 'DM Mono', monospace;

    /* Colors - PURE BLACK THEME */
    --sys-bg-0: #000000; /* Pure Black Background */
    --sys-bg-1: #0a0a0a; /* Almost Black (for headers/menus) */
    --sys-bg-2: #1f1f1f; /* Dark Grey (for borders/hover) */

    --sys-txt-0: #ffffff; /* Bright text */
    --sys-txt-1: #e5e5e5; /* Normal text */
    --sys-txt-muted: #888888; /* Muted text */

    --sys-accent: #ffffff; /* White accent for monochrome look */
    --sys-accent-hover: #cccccc;

    /* --- YouTube Variable Overrides --- */
    --yt-spec-base-background: var(--sys-bg-0) !important;
    --yt-spec-raised-background: var(--sys-bg-1) !important;
    --yt-spec-menu-background: var(--sys-bg-1) !important;
    --yt-spec-text-primary: var(--sys-txt-1) !important;
    --yt-spec-text-secondary: var(--sys-txt-muted) !important;
    --yt-spec-brand-icon-active: var(--sys-accent) !important;
    --yt-spec-wordmark-text: var(--sys-txt-0) !important;
    --ytd-searchbox-background: var(--sys-bg-0) !important;
    --ytd-searchbox-text-color: var(--sys-txt-1) !important;
}

/* Force Font Family */
body, button, input, textarea, select, #video-title, #content-text, yt-formatted-string {
    font-family: var(--font-system24) !important;
    letter-spacing: -0.05ch !important;
}

/* --- Unrounding (TUI Style) --- */
* {
    border-radius: 0px !important;
}

/* --- Logo Customization (Greyscale) --- */
#logo-icon, ytd-topbar-logo-renderer, .ytd-topbar-logo-renderer {
    filter: grayscale(100%) contrast(1.2) !important;
}

/* --- Layout & Color Adjustments --- */

/* Main Backgrounds */
ytd-app, #page-manager, #columns {
    background-color: var(--sys-bg-0) !important;
}

/* Header / Top Bar */
#masthead-container, #masthead {
    background-color: var(--sys-bg-0) !important; /* Made pure black */
    border-bottom: 2px solid var(--sys-bg-2);
}

/* Search Box */
ytd-searchbox {
    border: 2px solid var(--sys-bg-2) !important;
    box-shadow: none !important;
}
#search-icon-legacy {
    background-color: var(--sys-bg-1) !important;
    border: none !important;
    border-left: 2px solid var(--sys-bg-2) !important;
}
#search-icon-legacy:hover {
    background-color: var(--sys-bg-2) !important;
}
#search-icon-legacy:hover yt-icon {
    color: var(--sys-txt-0) !important;
}

/* Sidebar / Guide */
ytd-guide-renderer, ytd-mini-guide-renderer {
    background-color: var(--sys-bg-0) !important;
    border-right: 2px solid var(--sys-bg-2);
}
ytd-guide-entry-renderer:hover {
    background-color: var(--sys-bg-2) !important;
}
ytd-guide-entry-renderer[active] {
    background-color: var(--sys-bg-2) !important;
    color: var(--sys-txt-0) !important;
}
ytd-guide-entry-renderer[active] yt-icon {
    color: var(--sys-txt-0) !important;
}

/* Chips (Categories) */
yt-chip-cloud-chip-renderer {
    background-color: var(--sys-bg-0) !important;
    border: 2px solid var(--sys-bg-2) !important;
    color: var(--sys-txt-muted) !important;
}
yt-chip-cloud-chip-renderer[selected] {
    background-color: var(--sys-bg-2) !important;
    color: var(--sys-txt-0) !important;
    border-color: var(--sys-txt-0) !important;
}

/* Video Cards */
ytd-rich-item-renderer, ytd-compact-video-renderer {
    background-color: transparent !important;
}
#video-title {
    color: var(--sys-txt-1) !important;
    font-weight: 500 !important;
}
.ytd-channel-name {
    color: var(--sys-txt-muted) !important;
}

/* Progress Bar (Monochrome) */
.ytp-play-progress {
    background: var(--sys-txt-0) !important;
}
.ytp-scrubber-button {
    background: var(--sys-txt-0) !important;
    border-radius: 0 !important;
    transform: scale(0.8);
}
.ytp-load-progress {
    background: var(--sys-bg-2) !important;
}

/* Subscribe Button */
#subscribe-button button, .yt-spec-button-shape-next--filled {
    background-color: var(--sys-txt-0) !important;
    color: var(--sys-bg-0) !important;
    text-transform: lowercase !important;
    font-weight: 700 !important;
}
.yt-spec-button-shape-next--tonal {
    background-color: var(--sys-bg-2) !important;
    color: var(--sys-txt-1) !important;
}

/* Comments */
#content-text {
    color: var(--sys-txt-1) !important;
}
#author-text {
    color: var(--sys-txt-0) !important;
    font-weight: 700 !important;
}
